import { useSnackbar } from 'notistack'
import { useEffect, useRef, useState } from 'react'
import { useNavigate } from 'react-router'

import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline'
import UploadIcon from '@mui/icons-material/Upload'
import { Box, Button, Grid, Stack, TextField, Typography } from '@mui/material'

import { IMAGE_UPLOAD_MESSAGE } from 'src/data/messages'
import {
  PARTNER_BENEFIT_IMAGE_ALLOWED_TYPES,
  PARTNER_BENEFIT_IMAGE_LIMIT_BYTES,
  PARTNER_COUPON_MESSAGES
} from 'src/data/partnerBenefits'

import type { PartnerStore, PartnerStorePayload } from 'src/models/partnerBenefit'

type PartnerStoreFormValues = PartnerStorePayload

interface PartnerStoreFormProps {
  editingStore?: PartnerStore
  onCreatePartnerStore: (store: PartnerStoreFormValues) => Promise<unknown>
  onUpdatePartnerStore: (storeId: number, store: PartnerStoreFormValues) => Promise<unknown>
  onUploadPartnerStoreImage?: (storeId: number, image: File) => Promise<unknown>
  onDeletePartnerStoreImage?: (storeId: number) => Promise<unknown>
}

const getEmptyPartnerStoreFormValues = (): PartnerStoreFormValues => ({
  name: '',
  mapLink: '',
  imageUrl: ''
})

const getPartnerStoreFormValues = (store?: PartnerStore): PartnerStoreFormValues => {
  if (!store) return getEmptyPartnerStoreFormValues()

  return {
    name: store.name,
    mapLink: store.mapLink,
    imageUrl: store.imageUrl ?? ''
  }
}

const PartnerStoreForm: React.FC<PartnerStoreFormProps> = ({
  editingStore,
  onCreatePartnerStore,
  onUpdatePartnerStore,
  onUploadPartnerStoreImage,
  onDeletePartnerStoreImage
}) => {
  const navigate = useNavigate()
  const { enqueueSnackbar } = useSnackbar()
  const imageInputRef = useRef<HTMLInputElement>(null)
  const [storeFormValues, setStoreFormValues] = useState<PartnerStoreFormValues>(() =>
    getPartnerStoreFormValues(editingStore)
  )
  const [isSubmitting, setIsSubmitting] = useState(false)
  const isEditing = !!editingStore

  useEffect(() => {
    setStoreFormValues(getPartnerStoreFormValues(editingStore))
  }, [editingStore])

  const handleStoreTextFieldChange: React.ChangeEventHandler<HTMLInputElement> = event => {
    const { name, value } = event.target
    setStoreFormValues(prevStoreFormValues => ({ ...prevStoreFormValues, [name]: value }))
  }

  const handleStoreImageButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    imageInputRef.current?.click()
  }

  const handleStoreImageInputChange: React.ChangeEventHandler<HTMLInputElement> = async event => {
    const file = event.target.files?.[0]
    if (!file) return

    if (file.size > PARTNER_BENEFIT_IMAGE_LIMIT_BYTES) {
      enqueueSnackbar(IMAGE_UPLOAD_MESSAGE.TOO_LARGE_PROFILE, { variant: 'error' })
      event.target.value = ''
      return
    }

    if (!PARTNER_BENEFIT_IMAGE_ALLOWED_TYPES.includes(file.type)) {
      enqueueSnackbar(IMAGE_UPLOAD_MESSAGE.WRONG_FORMAT, { variant: 'error' })
      event.target.value = ''
      return
    }

    if (!editingStore || !onUploadPartnerStoreImage) {
      enqueueSnackbar('이미지 업로드는 가게 등록 후 수정 화면에서 사용할 수 있습니다.', { variant: 'warning' })
      event.target.value = ''
      return
    }

    try {
      setIsSubmitting(true)
      await onUploadPartnerStoreImage(editingStore.id, file)
      enqueueSnackbar('가게 이미지가 업로드되었습니다.', { variant: 'success' })
    } catch {
      enqueueSnackbar(IMAGE_UPLOAD_MESSAGE.UPLOAD_FAIL, { variant: 'error' })
    } finally {
      setIsSubmitting(false)
      event.target.value = ''
    }
  }

  const handleStoreFormSubmitClick: React.MouseEventHandler<HTMLButtonElement> = async () => {
    if (!storeFormValues.name.trim() || !storeFormValues.mapLink.trim()) {
      enqueueSnackbar(PARTNER_COUPON_MESSAGES.STORE_REQUIRE, { variant: 'warning' })
      return
    }

    try {
      setIsSubmitting(true)
      if (editingStore) {
        await onUpdatePartnerStore(editingStore.id, storeFormValues)
        enqueueSnackbar(PARTNER_COUPON_MESSAGES.UPDATE_STORE_SUCCESS, { variant: 'success' })
        navigate('/admin/benefit-stores')
        return
      }

      await onCreatePartnerStore(storeFormValues)
      enqueueSnackbar(PARTNER_COUPON_MESSAGES.ADD_STORE_SUCCESS, { variant: 'success' })
      setStoreFormValues(getEmptyPartnerStoreFormValues())
    } catch {
      return
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleStoreEditCancelButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate('/admin/benefit-stores')
  }

  const handleStoreImageDeleteButtonClick: React.MouseEventHandler<HTMLButtonElement> = async () => {
    if (!editingStore || !onDeletePartnerStoreImage) return

    try {
      setIsSubmitting(true)
      await onDeletePartnerStoreImage(editingStore.id)
      enqueueSnackbar('가게 이미지가 삭제되었습니다.', { variant: 'success' })
      setStoreFormValues(prevStoreFormValues => ({ ...prevStoreFormValues, imageUrl: '' }))
    } catch {
      return
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <Box>
      <Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" spacing={2} sx={{ mb: 3 }}>
        <Box>
          <Typography variant="h4">{isEditing ? '제휴 가게 수정' : '제휴 가게 등록'}</Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
            쿠폰에 연결할 가게 정보와 public 페이지에 표시될 위치 정보를 입력합니다.
          </Typography>
        </Box>
        <Button variant="outlined" href="/admin/benefit-stores">
          등록된 가게 리스트 보기
        </Button>
      </Stack>
      <Grid container spacing={2}>
        <Grid item xs={12} md={6}>
          <TextField
            fullWidth
            label="가게명"
            name="name"
            value={storeFormValues.name}
            onChange={handleStoreTextFieldChange}
          />
        </Grid>
        <Grid item xs={12} md={6}>
          <TextField
            fullWidth
            label="지도 링크"
            name="mapLink"
            value={storeFormValues.mapLink}
            onChange={handleStoreTextFieldChange}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            fullWidth
            label="이미지 URL"
            name="imageUrl"
            value={storeFormValues.imageUrl ?? ''}
            onChange={handleStoreTextFieldChange}
            helperText="이미지 업로드 API를 사용하지 않고 외부 이미지 URL을 직접 연결할 때 입력합니다."
          />
        </Grid>
        <Grid item xs={12}>
          <input
            ref={imageInputRef}
            type="file"
            accept={PARTNER_BENEFIT_IMAGE_ALLOWED_TYPES.join(',')}
            style={{ display: 'none' }}
            onChange={handleStoreImageInputChange}
          />
          <Stack direction={{ xs: 'column', sm: 'row' }} alignItems={{ xs: 'flex-start', sm: 'center' }} spacing={2}>
            <Button
              variant="outlined"
              startIcon={<UploadIcon />}
              onClick={handleStoreImageButtonClick}
              disabled={isSubmitting}
            >
              이미지 업로드
            </Button>
            {isEditing && editingStore.imageUrl && (
              <Button
                variant="outlined"
                color="error"
                startIcon={<DeleteOutlineIcon />}
                onClick={handleStoreImageDeleteButtonClick}
                disabled={isSubmitting}
              >
                이미지 삭제
              </Button>
            )}
            <Typography variant="body2" color="text.secondary">
              {isEditing
                ? 'jpg, jpeg, png, webp 이미지를 서버에 업로드할 수 있습니다.'
                : '이미지 업로드는 가게 등록 후 수정 화면에서 사용할 수 있습니다.'}
            </Typography>
          </Stack>
        </Grid>
        <Grid item xs={12}>
          <Stack direction="row" spacing={1.5} justifyContent="flex-end">
            {isEditing && (
              <Button variant="outlined" color="secondary" onClick={handleStoreEditCancelButtonClick}>
                수정 취소
              </Button>
            )}
            <Button variant="contained" color="success" onClick={handleStoreFormSubmitClick} disabled={isSubmitting}>
              {isEditing ? '가게 수정' : '가게 등록'}
            </Button>
          </Stack>
        </Grid>
      </Grid>
    </Box>
  )
}

export default PartnerStoreForm
